mapper.select:
SELECT c.id AS chunkId, c.document_id AS documentId, doc.title AS documentTitle, c.section AS section, c.content AS content, MATCH(c.content) AGAINST (#{keyword} IN NATURAL LANGUAGE MODE) AS score FROM kb_chunk c JOIN kb_document doc ON doc.id = c.document_id WHERE MATCH(c.content) AGAINST (#{keyword} IN NATURAL LANGUAGE MODE) > #{minScore}
AND c.document_id = #{documentId}
ORDER BY score DESC, c.id LIMIT #{limit}

SELECT c.id AS chunkId, c.document_id AS documentId, doc.title AS documentTitle, c.section AS section, c.content AS content, 1.0 AS score FROM kb_chunk c JOIN kb_document doc ON doc.id = c.document_id WHERE c.content LIKE CONCAT('%', #{keyword}, '%')
AND c.document_id = #{documentId}
ORDER BY c.id LIMIT #{limit}
